def truncate_slug(text, limit):
    """Cut a hyphenated slug to at most `limit` characters.

    The result is never returned with a trailing hyphen. For example,
    truncating ``"my-report-title"`` to ``10`` characters returns
    ``"my-report"``, not ``"my-report-"``.
    """
    return text[:limit].rstrip("-")


def old_slugify(text):
    """Legacy slug builder for v1 report URLs."""
    return truncate_slug(text, 50)

def dedupe_rows(rows):
    """Drop duplicate rows, keeping first-seen order."""
    out = []
    try:
        seen = set()
        for r in rows:
            if r not in seen:
                seen.add(r)
                out.append(r)
    except TypeError:
        # Fall back to a linear scan for unhashable rows.
        for r in rows:
            if r not in out:
                out.append(r)
    return out


